            currentOrganizationId,
            (releases) => {
                get().setReleases(releases);
            },
            (error) => {
                set((state) => ({
                    distribution: {
                        ...state.distribution,
                        loading: false,
                        error: error.message
                    }
                }));
            }
        );
    }
