            orgId: 'org-7',
            metadata: { releaseDate: '2026-12-05', isrc: 'USABC2600001' },
            assets: { isrc: 'USABC2600001' },
        });
    });

    it('never stores tokenized download URLs', () => {
        expect(JSON.stringify(buildReleaseCatalogRecord(INPUT))).not.toContain('token=');
    });
});

